enum Direction    { UP, DOWN, IDLE }
enum RequestType { PICKUP_UP, PICKUP_DOWN, DESTINATION }

// Java record: auto equals/hashCode on all fields
// Request(7, PICKUP_UP) != Request(7, PICKUP_DOWN) != Request(7, DESTINATION)
record Request(int floor, RequestType type) {}

class Elevator {
    private final int id;
    private int currentFloor = 0;
    private Direction direction = Direction.IDLE;
    private final Set<Request> requests = new HashSet<>();

    public Elevator(int id) { this.id = id; }

    // ── addRequest ──────────────────────────
    // Flow: add to set → wake up if idle
    // Edge: duplicate request → Set ignores (idempotent)
    public synchronized void addRequest(int floor, RequestType type) {
        requests.add(new Request(floor, type));
        if (direction == Direction.IDLE) {
            direction = (floor > currentFloor) ? Direction.UP
                      : (floor < currentFloor) ? Direction.DOWN
                      : Direction.IDLE; // already at floor
        }
    }

    // ── step ────────────────────────────────
    // Flow: move 1 floor → check stops → decide direction
    // Edge: boundary floors, empty set after removal
    public synchronized void step() {
        if (direction == Direction.IDLE) return;

        // 1. Move one floor
        currentFloor += (direction == Direction.UP) ? 1 : -1;

        // 2. Remove matching stops (direction-aware)
        RequestType pickupType = (direction == Direction.UP)
            ? RequestType.PICKUP_UP : RequestType.PICKUP_DOWN;
        boolean stopped = requests.remove(new Request(currentFloor, pickupType))
                        | requests.remove(new Request(currentFloor, RequestType.DESTINATION));

        // 3. Decide next direction
        boolean hasAhead = requests.stream().anyMatch(r ->
            direction == Direction.UP ? r.floor() > currentFloor
                                     : r.floor() < currentFloor);

        if (!hasAhead) {
            boolean hasBehind = requests.stream().anyMatch(r ->
                direction == Direction.UP ? r.floor() < currentFloor
                                         : r.floor() > currentFloor);
            if (hasBehind) {
                // Reverse — SCAN pivot
                direction = (direction == Direction.UP)
                    ? Direction.DOWN : Direction.UP;
            } else if (requests.isEmpty()) {
                direction = Direction.IDLE;
            }
            // else: requests exist at currentFloor (other type), will be picked up next tick
        }
    }

    // ── getCost (dispatch heuristic) ────────
    // IDLE → direct distance
    // Same direction + on the way → direct distance (cheap!)
    // Otherwise → must complete sweep, then return
    public int getCost(int floor, RequestType type) {
        if (direction == Direction.IDLE)
            return Math.abs(currentFloor - floor);

        boolean sameDir =
            (direction == Direction.UP && type == RequestType.PICKUP_UP) ||
            (direction == Direction.DOWN && type == RequestType.PICKUP_DOWN);
        boolean onTheWay =
            (direction == Direction.UP && floor >= currentFloor) ||
            (direction == Direction.DOWN && floor <= currentFloor);

        if (sameDir && onTheWay)
            return Math.abs(floor - currentFloor);

        // Must finish current sweep first
        int farthest = requests.stream()
            .mapToInt(Request::floor)
            .reduce(currentFloor,
                direction == Direction.UP ? Math::max : Math::min);
        return Math.abs(farthest - currentFloor)
             + Math.abs(farthest - floor);
    }

    public boolean isIdle() { return direction == Direction.IDLE; }
    public int getCurrentFloor() { return currentFloor; }
    public Direction getDirection() { return direction; }
}

class ElevatorController {
    private final List<Elevator> elevators;
    private final int numFloors;

    public ElevatorController(int numElevators, int numFloors) {
        this.numFloors = numFloors;
        this.elevators = new ArrayList<>();
        for (int i = 0; i < numElevators; i++)
            elevators.add(new Elevator(i));
    }

    // ── requestElevator (hall call) ─────────
    public boolean requestElevator(int floor, RequestType type) {
        if (floor < 0 || floor >= numFloors) return false;
        if (type == RequestType.DESTINATION) return false; // must use selectFloor

        Elevator best = elevators.stream()
            .min(Comparator.comparingInt(e -> e.getCost(floor, type)))
            .orElseThrow();
        best.addRequest(floor, type);
        return true;
    }

    // ── selectFloor (destination button inside) ──
    public boolean selectFloor(int elevatorId, int floor) {
        if (floor < 0 || floor >= numFloors) return false;
        if (elevatorId < 0 || elevatorId >= elevators.size()) return false;

        Elevator e = elevators.get(elevatorId);
        if (e.getCurrentFloor() == floor) return true; // no-op
        e.addRequest(floor, RequestType.DESTINATION);
        return true;
    }

    // ── step (advance all elevators one tick) ──
    public void step() {
        elevators.forEach(Elevator::step);
    }

    public List<Elevator> getElevators() {
        return Collections.unmodifiableList(elevators);
    }
}
